project_task.solution:
const LEVELS = {
  1: { level: 1, stars: 5, speed: 2 },
  2: { level: 2, stars: 8, speed: 3 },
  3: { level: 3, stars: 12, speed: 4 },
};

function loadLevel(n) {
  // return a Promise that resolves with LEVELS[n] after 100 ms (or rejects if it doesn't exist)
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (LEVELS[n]) resolve(LEVELS[n]);
      else reject(new Error(`Level not found: ${n}`));
    }, 100);
  });
}

async function startLevel(n) {
  const info = document.querySelector("#info");
  // write loading, await loadLevel(n), write the info; catch the error
  info.textContent = "Loading level…";
  try {
    const level = await loadLevel(n);
    info.textContent = `Level ${level.level}: ${level.stars} stars, speed ${level.speed}`;
  } catch (error) {
    info.textContent = `Error: ${error.message}`;
  }
}

startLevel(1);
